mapper.select:
select t.person_name,t.person_name personName,t.mmu_id,t.mmu_id mmuId,t.machine_id,t.machine_id
machineId,t.machine_code,t.machine_code machineCode,t.person_id,t.person_id personId,t.status_cd,t.status_cd
statusCd,t.person_type,t.person_type personType,t.community_id,t.community_id
communityId,t.machine_name,t.machine_name machineName
from monitor_machine_person t
where 1 =1

    and t.person_name= #{personName}


    and t.mmu_id= #{mmuId}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.person_id= #{personId}


    and t.status_cd= #{statusCd}


    and t.person_type= #{personType}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}

order by t.create_time desc

    limit #{page}, #{row}

